package net.civeira.phylax.features.access.userconsentpurposes.domain;

import java.time.LocalDateTime;
import java.time.ZoneId;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.features.access.consentpurpose.domain.ConsentPurposeReference;
import net.civeira.phylax.features.access.user.domain.UserReference;

class UserConsentPurposesChangeSetUnitTest {

  /**
   * @autogenerated CachedGenerator
   */
  @Test
  @DisplayName("Test a entity reference contruction")
  void test_user_consent_purposes_change_set_builder() {
    UserConsentPurposesChangeSet one = new UserConsentPurposesChangeSet().uid("one")
        .user(UserReference.of("one")).consentPurpose(ConsentPurposeReference.of("one"))
        .granted(true).decisionAt(LocalDateTime.of(1980, 8, 20, 0, 0)
            .atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime())
        .ipAddress("one").userAgent("one").version(1).newUid();
    one.uid("two");
    Assertions.assertEquals("two", one.getUid().get(), "Value must equals to the assigned value");
    one.unset("uid");
    Assertions.assertFalse(one.getUid().isPresent(), "After unset, the valeue must be dissapear");
    Assertions.assertEquals(UserReference.of("one"), one.getUser().get(),
        "Value must equals to the intial value");
    one.user(UserReference.of("two"));
    Assertions.assertEquals(UserReference.of("two"), one.getUser().get(),
        "Value must equals to the assigned value");
    one.unset("user");
    Assertions.assertFalse(one.getUser().isPresent(), "After unset, the valeue must be dissapear");
    Assertions.assertEquals(ConsentPurposeReference.of("one"), one.getConsentPurpose().get(),
        "Value must equals to the intial value");
    one.consentPurpose(ConsentPurposeReference.of("two"));
    Assertions.assertEquals(ConsentPurposeReference.of("two"), one.getConsentPurpose().get(),
        "Value must equals to the assigned value");
    one.unset("consentPurpose");
    Assertions.assertFalse(one.getConsentPurpose().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(true, one.getGranted().get(), "Value must equals to the intial value");
    one.granted(false);
    Assertions.assertEquals(false, one.getGranted().get(),
        "Value must equals to the assigned value");
    one.unset("granted");
    Assertions.assertFalse(one.getGranted().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(
        LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime(),
        one.getDecisionAt().get(), "Value must equals to the intial value");
    one.decisionAt(
        LocalDateTime.of(1981, 9, 6, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime());
    Assertions.assertEquals(
        LocalDateTime.of(1981, 9, 6, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime(),
        one.getDecisionAt().get(), "Value must equals to the assigned value");
    one.unset("decisionAt");
    Assertions.assertFalse(one.getDecisionAt().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals("one", one.getIpAddress().get(),
        "Value must equals to the intial value");
    one.ipAddress("two");
    Assertions.assertEquals("two", one.getIpAddress().get(),
        "Value must equals to the assigned value");
    one.unset("ipAddress");
    Assertions.assertFalse(one.getIpAddress().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals("one", one.getUserAgent().get(),
        "Value must equals to the intial value");
    one.userAgent("two");
    Assertions.assertEquals("two", one.getUserAgent().get(),
        "Value must equals to the assigned value");
    one.unset("userAgent");
    Assertions.assertFalse(one.getUserAgent().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(0, one.getVersion().get(), "Value must equals to the intial value");
    one.version(2);
    Assertions.assertEquals(2, one.getVersion().get(), "Value must equals to the assigned value");
    one.unset("version");
    Assertions.assertFalse(one.getVersion().isPresent(),
        "After unset, the valeue must be dissapear");
  }
}
